"""Exercise the production template unchanged with deterministic COM/IPC adapters."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def method(contents, marker):
    if contents.count(marker) != 1:
        raise ValueError(f"Unexpected method layout: {marker}")
    start = contents.index(marker)
    brace = contents.index("{", start)
    depth = 1
    end = brace + 1
    while depth and end < len(contents):
        depth += (contents[end] == "{") - (contents[end] == "}")
        end += 1
    if depth:
        raise ValueError("Unclosed production method")
    return start, end


def generate(source, output):
    header = source / "bridge/src/client/lockable_buffer.h"
    contents = header.read_text(encoding="utf-8")
    marker = "template <typename T>"
    if contents.count(marker) != 1:
        raise ValueError("Unexpected LockableBuffer template layout; refusing a partial test")
    template = marker + contents.split(marker, 1)[1]
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text('#include "buffer_contract_support.h"\n' + template
                      + '\n#include "buffer_contract_cases.cpp"\n', encoding="utf-8")


def generate_constants(source, output):
    device = (source / "bridge/src/client/d3d9_device.cpp").read_text(encoding="utf-8")
    start, end = method(device, "HRESULT BaseDirect3DDevice9Ex_LSS::setShaderConstants(")
    start = device.rindex("template <ShaderType", 0, start)
    base = (source / "bridge/src/client/d3d9_device_base.h").read_text(encoding="utf-8")
    invalidate_start, invalidate_end = method(base, "void invalidateDataState()")
    invalidate = base[invalidate_start:invalidate_end].replace("void invalidateDataState()", "void BaseDirect3DDevice9Ex_LSS::invalidateDataState()", 1)
    output.parent.mkdir(parents=True, exist_ok=True)
    # Keep the production method intact and isolate its legacy signed loops
    # and constant enum conditions; the rest still compiles with /W4 /WX.
    output.write_text('#include "constant_diagnostics_support.h"\n'
                      + '#ifdef _MSC_VER\n#pragma warning(push)\n#pragma warning(disable: 4018 4127)\n#endif\n'
                      + device[start:end]
                      + '\n#ifdef _MSC_VER\n#pragma warning(pop)\n#endif\n'
                      + invalidate + '\n#include "constant_diagnostics_cases.cpp"\n', encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, default=ROOT / ".deps/dxvk-remix")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--constants", action="store_true")
    args = parser.parse_args()
    (generate_constants if args.constants else generate)(args.source, args.output)
